style.css:
@-moz-document domain("youtube.com") {
/* Main background areas */
  html, body, ytd-app, #page-manager, ytd-watch-flexy {
    background-color: #000000 !important;
  }

  /* Comments and sidebar */
  #comments, #secondary, ytd-comments, ytd-watch-next-secondary-results-renderer {
    background-color: #000000 !important;
  }

  /* Top bar (masthead) */
  ytd-masthead, 
  #container.ytd-masthead, 
  #masthead-container {
    background-color: #000000 !important;
    border-bottom: none !important;
    box-shadow: none !important;
  }

  /* Remove shadows for consistency */
  ytd-masthead::before,
  ytd-masthead::after {
    box-shadow: none !important;
  }

  /* Make all text white for readability */
  * {
    color: #ffffff !important;
  }
}
